begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select no_plan();
select ok((select bool_and(rowsecurity) from pg_tables where schemaname='public' and tablename in ('group_schedule_series','group_schedule_slots','lessons','lesson_expected_students','scheduling_events','lesson_generation_batches')),'Scheduling tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.lesson_expected_students','select'),'Raw expected roster is private');
select ok(not has_table_privilege('authenticated','public.scheduling_events','select'),'Raw scheduling snapshots are private');
select ok(not has_table_privilege('authenticated','public.lessons','insert'),'Lesson mutations require checked commands');
create temporary table scheduling_scope(label text primary key,id uuid);grant select,insert on scheduling_scope to authenticated;
create temporary table scheduling_values(label text primary key,value jsonb);grant select,insert on scheduling_values to authenticated;
insert into auth.users(id,email,email_confirmed_at) values('99999700-0000-0000-0000-000000000001','native-schedule-owner@example.test',now()),('99999700-0000-0000-0000-000000000002','native-schedule-teacher@example.test',now()),('99999700-0000-0000-0000-000000000003','native-schedule-other@example.test',now());
set local role authenticated;set local request.jwt.claim.sub='99999700-0000-0000-0000-000000000001';
insert into scheduling_scope select 'tenant',public.create_business('Native scheduling');
insert into scheduling_scope select 'branch',id from public.branches where tenant_id=(select id from scheduling_scope where label='tenant') limit 1;
insert into public.branches(tenant_id,name) select id,'Other scheduled branch' from scheduling_scope where label='tenant';
insert into scheduling_scope select 'second',id from public.branches where tenant_id=(select id from scheduling_scope where label='tenant') and name='Other scheduled branch';
insert into scheduling_scope select 'course',public.save_course((select id from scheduling_scope where label='tenant'),null,gen_random_uuid(),0,'{"name":"Scheduling course","standard_price":"750000.10","pricing_model":"monthly"}');
insert into scheduling_scope select 'room',public.save_classroom((select id from scheduling_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from scheduling_scope where label='branch'),'name','Room A','capacity','2'));
insert into scheduling_scope select 'room2',public.save_classroom((select id from scheduling_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from scheduling_scope where label='second'),'name','Room B','capacity','2'));
insert into scheduling_scope select 'group',public.save_study_group((select id from scheduling_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from scheduling_scope where label='branch'),'course_id',(select id from scheduling_scope where label='course'),'name','Group A','capacity','2','start_date',((now() at time zone 'Asia/Tashkent')::date-7)::text));
insert into scheduling_scope select 'group2',public.save_study_group((select id from scheduling_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from scheduling_scope where label='second'),'course_id',(select id from scheduling_scope where label='course'),'name','Group B','capacity','2','start_date',((now() at time zone 'Asia/Tashkent')::date-7)::text));
insert into scheduling_scope select 'teacher',public.save_employee((select id from scheduling_scope where label='tenant'),null,'Native scheduling teacher','','native-schedule-teacher@example.test','Teacher','active',(now() at time zone 'Asia/Tashkent')::date,'',array[(select id from scheduling_scope where label='branch'),(select id from scheduling_scope where label='second')]);
create temporary table scheduling_token(token text);grant select,insert on scheduling_token to authenticated;
insert into scheduling_token select public.create_employee_invitation((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='teacher'),(select id from public.business_roles where tenant_id=(select id from scheduling_scope where label='tenant') and system_key='teacher'));
set local request.jwt.claim.sub='99999700-0000-0000-0000-000000000002';select public.accept_employee_invitation((select token from scheduling_token));
set local request.jwt.claim.sub='99999700-0000-0000-0000-000000000001';
select public.set_group_teachers((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),gen_random_uuid(),1,array[(select id from scheduling_scope where label='teacher')],(select id from scheduling_scope where label='teacher'),'Teaching assignment');
select public.set_group_teachers((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group2'),gen_random_uuid(),1,array[(select id from scheduling_scope where label='teacher')],(select id from scheduling_scope where label='teacher'),'Teaching assignment');
select public.change_group_status((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),gen_random_uuid(),2,'active','Start teaching');
insert into scheduling_scope select 'student',public.save_student((select id from scheduling_scope where label='tenant'),gen_random_uuid(),null,'{"first_name":"Original lesson student","phone":"998909991111"}','{}',array[(select id from scheduling_scope where label='branch')]);
insert into scheduling_scope select 'enrollment',public.create_student_enrollment((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),(select id from scheduling_scope where label='student'),gen_random_uuid(),jsonb_build_object('enrollment_date',(now() at time zone 'Asia/Tashkent')::date::text,'effective_start_date',((now() at time zone 'Asia/Tashkent')::date-7)::text,'status','active','agreed_price','750000.10','pricing_model','monthly'));
insert into scheduling_values select 'lesson_data',jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date+7)::text||'T10:00','local_end',((now() at time zone 'Asia/Tashkent')::date+7)::text||'T11:00','timezone','Asia/Tashkent','teacher_id',(select id from scheduling_scope where label='teacher'),'classroom_id',(select id from scheduling_scope where label='room'),'title','Native future lesson');
insert into scheduling_scope select 'lesson',public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),null,gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data'),'Native lesson planning');
select is((public.lesson_details((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='lesson'))->'lesson'->>'starts_at')::timestamptz,(((now() at time zone 'Asia/Tashkent')::date+7)::text||'T05:00:00Z')::timestamptz,'Local Tashkent time becomes the correct UTC instant');
select throws_ok($$select public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group2'),null,gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('classroom_id',(select id from scheduling_scope where label='room2')),'Cross-branch collision')$$,'23P01','Lesson conflict: group, teaching employee or classroom is already booked','Teacher overlap across branches is rejected');
select lives_ok($$select public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),null,gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date+7)::text||'T11:00','local_end',((now() at time zone 'Asia/Tashkent')::date+7)::text||'T12:00'),'Adjacent lesson')$$,'Adjacent intervals do not conflict');
insert into scheduling_values select 'slot_data',jsonb_build_object('weekday',extract(isodow from (now() at time zone 'Asia/Tashkent')::date+14)::integer::text,'start_time','10:00','end_time','11:00','timezone','Asia/Tashkent','effective_from',((now() at time zone 'Asia/Tashkent')::date+14)::text,'effective_to',((now() at time zone 'Asia/Tashkent')::date+28)::text,'teacher_id',(select id from scheduling_scope where label='teacher'),'classroom_id',(select id from scheduling_scope where label='room'));
insert into scheduling_scope select 'slot',public.save_group_schedule((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),null,gen_random_uuid(),0,(select value from scheduling_values where label='slot_data'),'Weekly teaching plan');
select throws_ok($$select public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group2'),null,gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date+14)::text||'T10:00','local_end',((now() at time zone 'Asia/Tashkent')::date+14)::text||'T11:00','classroom_id',(select id from scheduling_scope where label='room2')),'Ungenerated reservation')$$,'23P01','Schedule conflict: an ungenerated weekly occurrence reserves this resource','Weekly plan reserves resources before generation');
insert into scheduling_values select 'batch',public.generate_group_lessons((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),'99999700-0000-0000-0000-000000000010',((now() at time zone 'Asia/Tashkent')::date+14)::text,((now() at time zone 'Asia/Tashkent')::date+21)::text);
select is((select value->>'created_count' from scheduling_values where label='batch'),'2','Generation creates actual recurring lessons');
select is(public.generate_group_lessons((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),'99999700-0000-0000-0000-000000000010',((now() at time zone 'Asia/Tashkent')::date+14)::text,((now() at time zone 'Asia/Tashkent')::date+21)::text)::text,(select value::text from scheduling_values where label='batch'),'Matching generation retry returns original receipt');
select is(public.generate_group_lessons((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),gen_random_uuid(),((now() at time zone 'Asia/Tashkent')::date+14)::text,((now() at time zone 'Asia/Tashkent')::date+21)::text)->>'existing_count','2','New requests do not duplicate occurrences');
insert into scheduling_scope select 'root',id from public.lessons where tenant_id=(select id from scheduling_scope where label='tenant') and occurrence_date=(now() at time zone 'Asia/Tashkent')::date+14;
insert into scheduling_scope select 'next',id from public.lessons where tenant_id=(select id from scheduling_scope where label='tenant') and occurrence_date=(now() at time zone 'Asia/Tashkent')::date+21;
select public.transition_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='root'),gen_random_uuid(),1,'cancelled','Cancel retained occurrence');
select is(public.generate_group_lessons((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),gen_random_uuid(),((now() at time zone 'Asia/Tashkent')::date+14)::text,((now() at time zone 'Asia/Tashkent')::date+21)::text)->>'created_count','0','Cancelled occurrence is never resurrected');
insert into scheduling_scope select 'replacement',public.reschedule_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='next'),gen_random_uuid(),1,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date+21)::text||'T13:00','local_end',((now() at time zone 'Asia/Tashkent')::date+21)::text||'T14:00'),'Move future lesson');
select is(public.lesson_details((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='next'))->'lesson'->>'status','rescheduled','Original lesson retains rescheduled status');
select is(public.lesson_details((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='replacement'))->'lesson'->>'rescheduled_from_id',(select id::text from scheduling_scope where label='next'),'Replacement retains its source ID');
select throws_ok($$select public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),(select id from scheduling_scope where label='lesson'),gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data'),'Stale lesson edit')$$,'40001','Lesson changed; reload','Stale lesson version rejected');
insert into scheduling_scope select 'past',public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),null,gen_random_uuid(),0,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date-1)::text||'T10:00','local_end',((now() at time zone 'Asia/Tashkent')::date-1)::text||'T11:00'),'Record historical lesson');
select public.transition_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='past'),gen_random_uuid(),1,'in_progress','Start historical record');
select public.transition_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='past'),gen_random_uuid(),2,'completed','Complete historical record');
select is(public.lesson_expected_roster((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='past'))->'rows'->0->>'customer_id',(select id::text from scheduling_scope where label='student'),'Captured roster references original Student Profile');
select ok(public.lesson_expected_roster((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='past'))->>'captured_at' is not null,'Lifecycle freezes expected roster');
select throws_ok($$select public.save_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='group'),(select id from scheduling_scope where label='past'),gen_random_uuid(),3,(select value from scheduling_values where label='lesson_data')||jsonb_build_object('local_start',((now() at time zone 'Asia/Tashkent')::date-1)::text||'T10:00','local_end',((now() at time zone 'Asia/Tashkent')::date-1)::text||'T11:00'),'Rewrite completed')$$,'P0001','Completed and terminal lessons cannot be overwritten','Completed lesson cannot be overwritten');
set local request.jwt.claim.sub='99999700-0000-0000-0000-000000000002';
select is(public.lesson_details((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='lesson'))->>'can_manage','false','Teacher can read without management');
select throws_ok($$select public.transition_lesson((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='lesson'),gen_random_uuid(),1,'cancelled','Teacher cancellation')$$,'42501','Lesson lifecycle denied','Teacher cannot cancel lessons');
select ok(not(public.lesson_expected_roster((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='past'))->'rows'->0?'agreed_price'),'Teacher expected roster exposes no tuition');
select throws_ok($$select public.financial_report((select id from scheduling_scope where label='tenant'),'payments')$$,'42501',null,'Teaching permissions expose no financial report');
select throws_ok($$select * from public.lesson_expected_students$$,'42501',null,'Teacher cannot query raw roster snapshots');
set local request.jwt.claim.sub='99999700-0000-0000-0000-000000000003';
select throws_ok($$select public.lesson_details((select id from scheduling_scope where label='tenant'),(select id from scheduling_scope where label='lesson'))$$,'42501','Lesson access denied','Foreign user cannot retrieve lesson by ID');
select is((select count(*)::integer from public.lessons where tenant_id=(select id from scheduling_scope where label='tenant')),0,'Direct lesson SELECT enforces tenant RLS');
set local request.jwt.claim.sub='';
select throws_ok($$select public.lesson_directory((select id from scheduling_scope where label='tenant'))$$,'42501','Lesson directory denied','Subjectless timetable reads denied');
reset role;
select throws_ok($$select private.academic_instant('2026-03-08T02:30','America/New_York')$$,'P0001','Ambiguous or nonexistent local time; choose an unambiguous time or split the effective schedule period','DST gap is rejected');
select throws_ok($$select private.academic_instant('2026-11-01T01:30','America/New_York')$$,'P0001','Ambiguous or nonexistent local time; choose an unambiguous time or split the effective schedule period','DST duplicate hour is rejected');
select throws_ok($$select private.academic_instant('2026-04-05T01:45','Australia/Lord_Howe')$$,'P0001','Ambiguous or nonexistent local time; choose an unambiguous time or split the effective schedule period','Half-hour DST ambiguity is rejected');
select throws_ok($$select private.academic_instant('2026-10-04T02:15','Australia/Lord_Howe')$$,'P0001','Ambiguous or nonexistent local time; choose an unambiguous time or split the effective schedule period','Half-hour DST gap is rejected');
select throws_ok($$delete from public.lesson_expected_students where tenant_id=(select id from scheduling_scope where label='tenant')$$,'23514','Academic configuration history is immutable','Expected roster snapshots are retained');
select is((select count(*)::integer from public.financial_transactions where tenant_id=(select id from scheduling_scope where label='tenant')),0,'Scheduling posts no financial transactions');
set constraints all immediate;select * from finish();rollback;
